INSERT INTO `companies` (`id`, `name_ar`, `name_en`, `description_ar`, `description_en`, `title_ar`, `title_en`, `country`, `count_vote`, `link`, `image`, `active`, `regulation`, `stars`, `category`, `orders`, `created_at`, `updated_at`) VALUES
(3, 'XTP', 'XTP', NULL, 'Our mission is to provide solutions that allow our clients\' money to work for them in many different ways. We believe that all these possibilities can be accessible through one convenient app.', NULL, NULL, 'Poland', 1, 'https://www.xtb.com/int', 'content/companies/f96c9674-e964-40a1-946e-e022e7ecf583.png', 1, 'KNF, DFSA, FCA, CYSEC, IFSC', '4', 'Top 100 Member', 3, '2025-08-03 10:42:58', '2025-08-12 08:34:21'),
(4, 'ADSS', 'ADSS', NULL, 'We provide our traders with the highest quality investment opportunities and most rewarding trading experience – with multi-asset trading technology, a personalised view of the markets, access to liquidity and instruments, and support from our experienced, highly qualified team that offer highly professional customer service.', NULL, NULL, 'UAE', 0, 'https://www.adss.com/', 'content/companies/0c83fc58-9bb5-4dd9-bf7d-ad0eedd143bf.jpeg', 1, 'CB', '3', 'Top 100 Member', 222, '2025-08-03 11:33:34', '2025-08-12 08:34:21'),
(5, 'MultiBank Group', 'MultiBank Group', NULL, 'MultiBank Group was established in California, USA, in 2005. Since then, we have evolved into one of the largest financial derivatives providers worldwide, with a current paid-up capital of over $322 million. We service an extensive client-base of over 2,000,000+ customers from across 100 countries.', NULL, NULL, 'BVI', 3, 'https://multibankfx.com/en', 'content/companies/8796b2fb-77cb-4151-821e-4e3a7f29c534.png', 1, 'FSC', '4', 'Top 100 Member', 223, '2025-08-04 08:04:24', '2025-08-12 08:34:21'),
(6, 'XS.com', 'XS.com', 'The XS Group (operating under the brand name “XS” or “XS.com”) is a Global Multi-Asset Broker providing access to trade a wide range of financial products.\r\n\r\nEstablished in Australia in 2010, XS.com has grown into a global market leader in the FinTech, financial services and online trading industry with licences in various jurisdictions and offices in different locations around the globe.', 'The XS Group (operating under the brand name “XS” or “XS.com”) is a Global Multi-Asset Broker providing access to trade a wide range of financial products.\r\n\r\nEstablished in Australia in 2010, XS.com has grown into a global market leader in the FinTech, financial services and online trading industry with licences in various jurisdictions and offices in different locations around the globe.', NULL, NULL, 'Austrlia', 6, 'https://www.xs.com/en/', 'content/companies/d6e96a87-4497-4eaa-9e5f-e420100f7d34.png', 1, 'ASIC, CYSEC,FSA', '2.5', 'Top 100 Member', 4, '2025-08-04 08:12:51', '2025-08-13 12:46:38'),
(7, 'XM', 'XM', 'We pioneered the strict no requotes, no rejections policy that established our reputation. To prevent slippage and keep your strategy aligned with real-time market prices, 99% of all trades are executed in less than one second.', 'We pioneered the strict no requotes, no rejections policy that established our reputation. To prevent slippage and keep your strategy aligned with real-time market prices, 99% of all trades are executed in less than one second.', NULL, NULL, 'UK', 0, NULL, 'content/companies/9d099d95-269b-4774-a868-009d8fd781af.jpeg', 1, 'FCA', '2.5', 'Top 100 Member', 221, '2025-08-04 08:47:44', '2025-08-12 08:34:21'),
(8, 'Equiti', 'Equiti', 'Equiti is a pioneering fintech firm and world-class provider of online trading technology and multi-asset financial products.\r\n\r\nWith over 300 global specialists and 24/6 customer service in 9 languages, Equiti provides clients with access to individual, professional and institutional brokerage services across various affiliates and subsidiaries.\r\n\r\nEquiti Group’s global footprint spans across Europe, the Middle East, Asia and Africa.\r\n\r\nThe six regulated entities within Equiti Group include Equiti Capital UK Ltd regulated by the UK’s Financial Conduct Authority, Equiti Group Limited Jordan regulated and licensed by the Jordan Securities Commission, Equiti Securities Currencies Brokers LLC regulated and licensed by UAE\'s Security and Commodities Authority, EGM Securities regulated and licensed by the Capital Markets Authority, Equiti Brokerage (Seychelles) regulated and licensed by the Seychelles Financial Services Authority, and Equiti AM regulated and licensed by the Central Bank of Armenia.', 'Equiti is a pioneering fintech firm and world-class provider of online trading technology and multi-asset financial products.\r\n\r\nWith over 300 global specialists and 24/6 customer service in 9 languages, Equiti provides clients with access to individual, professional and institutional brokerage services across various affiliates and subsidiaries.\r\n\r\nEquiti Group’s global footprint spans across Europe, the Middle East, Asia and Africa.\r\n\r\nThe six regulated entities within Equiti Group include Equiti Capital UK Ltd regulated by the UK’s Financial Conduct Authority, Equiti Group Limited Jordan regulated and licensed by the Jordan Securities Commission, Equiti Securities Currencies Brokers LLC regulated and licensed by UAE\'s Security and Commodities Authority, EGM Securities regulated and licensed by the Capital Markets Authority, Equiti Brokerage (Seychelles) regulated and licensed by the Seychelles Financial Services Authority, and Equiti AM regulated and licensed by the Central Bank of Armenia.', NULL, NULL, 'Jordan', 1, 'https://www1.equiti.com/', 'content/companies/8a74c81c-aaf7-47d5-aeb7-21472ad81b3f.png', 1, 'SC', '4', 'Top 100 Member', 220, '2025-08-04 11:34:35', '2025-08-12 08:34:21'),
(9, 'Exness', 'Exness', 'The Exness way is about balance\r\nWe set out in 2008 to balance ethics and technology to reimagine how the ideal trading experience could be. Today, as a leader in the industry of CFD trading, servicing over 1 million active traders, we know we’re on the right path.\r\n\r\nWe built our proprietary trading features so we could offer something unique, something no other broker had ever attempted. We were the first to offer traders instant withdrawals¹, stop out protection and more. Features that give traders an edge.\r\n\r\nTrading is just one part of the picture. We believe in creating ecosystems of benefit for traders, partners, and employees to thrive within. Making what once was deemed impossible, a reality', 'The Exness way is about balance\r\nWe set out in 2008 to balance ethics and technology to reimagine how the ideal trading experience could be. Today, as a leader in the industry of CFD trading, servicing over 1 million active traders, we know we’re on the right path.\r\n\r\nWe built our proprietary trading features so we could offer something unique, something no other broker had ever attempted. We were the first to offer traders instant withdrawals¹, stop out protection and more. Features that give traders an edge.\r\n\r\nTrading is just one part of the picture. We believe in creating ecosystems of benefit for traders, partners, and employees to thrive within. Making what once was deemed impossible, a reality', NULL, NULL, 'Seychelles', 1, 'https://www.exness.com/', 'content/companies/4a48c8f0-7b74-4a3c-9cb7-2640ef2c6fc6.jpeg', 1, 'FSA', '4', 'Top 100 Member', 219, '2025-08-04 11:37:50', '2025-08-14 09:18:42'),
(10, 'Tradeview', 'Tradeview', 'Since 2004, Tradeview has led the industry in electronic market access for forex and equities by offering innovative solutions.\r\n\r\nWe’re not just a broker, we are your gateway to leading trading technology, innovation, and account security.\r\n\r\nWe aim for streamlined account management and fair issue resolution, staying ahead in our industry by fostering strong relationships with clients, partners, regulators, and tech providers.', 'Since 2004, Tradeview has led the industry in electronic market access for forex and equities by offering innovative solutions.\r\n\r\nWe’re not just a broker, we are your gateway to leading trading technology, innovation, and account security.\r\n\r\nWe aim for streamlined account management and fair issue resolution, staying ahead in our industry by fostering strong relationships with clients, partners, regulators, and tech providers.', NULL, NULL, 'Malta', 0, 'https://www.tvmarkets.com/en/', 'content/companies/6b7d04e4-1230-48a2-ae4b-fb4df60fc8cd.jpeg', 1, 'MFSA', '4', 'Top 100 Member', 218, '2025-08-05 07:07:47', '2025-08-12 08:34:21'),
(11, 'InstaForex', 'InstaForex', 'InstaForex guarantees seamless and safe access to the forex market regardless of existing market conditions. Our team has a vast experience in the sphere of client and partner support. Our employees are young and talented specialists in the financial services field.\r\n\r\nTrading conditions at our company correlate with basic trends in the brokerage industry. We strive to comply with the highest quality standards in both trading services and client support spheres. By now, over 7 000 000 clients all over the world have appreciated our efforts.', 'InstaForex guarantees seamless and safe access to the forex market regardless of existing market conditions. Our team has a vast experience in the sphere of client and partner support. Our employees are young and talented specialists in the financial services field.\r\n\r\nTrading conditions at our company correlate with basic trends in the brokerage industry. We strive to comply with the highest quality standards in both trading services and client support spheres. By now, over 7 000 000 clients all over the world have appreciated our efforts.', NULL, NULL, 'BVI', 1, 'https://www.instaforex.com/ar/', 'content/companies/9cec6a1e-6c3f-4d2b-9971-95baddf09625.png', 1, 'FSC', '3', 'Top 100 Member', 217, '2025-08-05 07:10:53', '2025-08-12 08:34:21'),
(12, 'Vantage', 'Vantage', 'For more than 15 years, we’ve purpose-built our platform and services to help you trade seamlessly and better capitalise on market opportunities. Our Vantage ecosystem serves not only as a platform for investing in financial assets, but also a hub for learning, exploring, and connecting with other like-minded investors.\r\n\r\nWe are an award-winning, multi-asset broker with over 15 years of market experience. At Vantage, we offer traders access to diverse range of 1,000+ CFD products, including forex, indices, commodities, shares, ETFs, and bonds. We are here to provide you with tools and support to help you navigate the markets with confidence.', 'For more than 15 years, we’ve purpose-built our platform and services to help you trade seamlessly and better capitalise on market opportunities. Our Vantage ecosystem serves not only as a platform for investing in financial assets, but also a hub for learning, exploring, and connecting with other like-minded investors.\r\n\r\nWe are an award-winning, multi-asset broker with over 15 years of market experience. At Vantage, we offer traders access to diverse range of 1,000+ CFD products, including forex, indices, commodities, shares, ETFs, and bonds. We are here to provide you with tools and support to help you navigate the markets with confidence.', NULL, NULL, 'Cayman Isl', 0, 'https://www.vantagemarkets.com/', 'content/companies/4fbac718-60a2-4f22-87ad-90baba3a064f.png', 1, 'CIMA', '4', 'Top 100 Member', 216, '2025-08-05 07:13:02', '2025-08-12 08:34:21'),
(13, 'Tickmill', 'Tickmill', 'Tickmill is a trading name of Tickmill Ltd, a member of Tickmill Group, which is regulated by the Seychelles Financial Services Authority (FSA).\r\n\r\nWith a proven track record of strong financial results and stable growth, Tickmill has put itself in an enviable position as a trusted market leader and innovator.', 'Tickmill is a trading name of Tickmill Ltd, a member of Tickmill Group, which is regulated by the Seychelles Financial Services Authority (FSA).\r\n\r\nWith a proven track record of strong financial results and stable growth, Tickmill has put itself in an enviable position as a trusted market leader and innovator.', NULL, NULL, 'UK', 0, 'https://www.tickmill.com/', 'content/companies/ea5095e7-ec2f-4237-9680-34b5de2cdad0.png', 1, 'FCA', '2.5', 'Top 100 Member', 215, '2025-08-05 07:17:07', '2025-08-12 08:34:21'),
(14, 'Traders Hub', 'Traders Hub', 'Traders’ Hub is an Emirati-owned and managed brokerage firm, headquartered in Abu Dhabi, the capital of the UAE. Recognized as a trusted leader in investments and global trading, we offer clients secure and transparent access to financial markets worldwide. Founded on the principles of innovation and client focus, we provide cutting-edge trading platforms, competitive trading conditions, and tailored investment solutions. Rooted in Emirati values and backed by global expertise, Traders’ Hub empowers individual traders, businesses, and institutions to achieve growth and success in dynamic financial markets.', 'Traders’ Hub is an Emirati-owned and managed brokerage firm, headquartered in Abu Dhabi, the capital of the UAE. Recognized as a trusted leader in investments and global trading, we offer clients secure and transparent access to financial markets worldwide. Founded on the principles of innovation and client focus, we provide cutting-edge trading platforms, competitive trading conditions, and tailored investment solutions. Rooted in Emirati values and backed by global expertise, Traders’ Hub empowers individual traders, businesses, and institutions to achieve growth and success in dynamic financial markets.', NULL, NULL, 'UAE', 0, 'https://tradershub.ae/', 'content/companies/97d48148-7f83-4edf-8e3a-219acb98766f.jpeg', 1, 'SCA', '2.5', 'Top 100 Member', 214, '2025-08-05 07:19:54', '2025-08-12 08:34:21'),
(15, 'ATFX', 'ATFX', 'At ATFX, we believe there is a better way to trade the financial markets. With advanced technology, first-class products and services, and continuous education, we provide you with the best possible trading experience. Our customer-centric approach means that you come first, second and third on our priority list.', 'At ATFX, we believe there is a better way to trade the financial markets. With advanced technology, first-class products and services, and continuous education, we provide you with the best possible trading experience. Our customer-centric approach means that you come first, second and third on our priority list.', NULL, NULL, 'Mauritius', 0, 'https://www.atfx.com/', 'content/companies/b5823c4e-b306-46df-a00a-dfe6bde2d14e.png', 1, 'FSC', '3', 'Top 100 Member', 213, '2025-08-05 07:24:43', '2025-08-12 08:34:21'),
(16, 'FxPro', 'FxPro', 'Ever since our establishment, FxPro has successfully expanded to serve retail and institutional clients in more than 170 countries - and we are still growing.', 'Ever since our establishment, FxPro has successfully expanded to serve retail and institutional clients in more than 170 countries - and we are still growing.', NULL, NULL, 'UK', 0, 'https://www.fxpro.com/', 'content/companies/031ae748-6d42-492b-bc27-9a5d3636d69b.png', 1, 'FCA', '3.5', 'Top 100 Member', 212, '2025-08-05 07:28:37', '2025-08-12 08:34:21'),
(18, 'ICM.com', 'ICM.com', 'Established in 2009 in the United Kingdom, ICM.com is a multi-regulated fintech service provider offering access to over 5,000 assets across global markets for both retail and institutional clients. Since its inception, ICM.com has expanded rapidly to serve professional and institutional investors worldwide. The company maintains regional offices across the United Kingdom, Europe, Asia, Latin America, the Middle East, Africa, and other key financial hubs.', 'Established in 2009 in the United Kingdom, ICM.com is a multi-regulated fintech service provider offering access to over 5,000 assets across global markets for both retail and institutional clients. Since its inception, ICM.com has expanded rapidly to serve professional and institutional investors worldwide. The company maintains regional offices across the United Kingdom, Europe, Asia, Latin America, the Middle East, Africa, and other key financial hubs.', NULL, NULL, 'UK', 0, 'https://www.icm.com/', 'content/companies/8358cc01-b28a-43f7-9f5e-535d63ced1fe.png', 1, 'FSC Mauritius', '3.5', 'Top 100 Member', 211, '2025-08-05 07:35:01', '2025-08-12 08:34:21'),
(19, 'Windsor Brokers', 'Windsor Brokers', 'We believe everyone should have the right to access and trade the financial markets in a fair, efficient, and safe manner. It is this belief that led us to the establishment of Windsor Brokers back in 1988.\r\n\r\nFor the past 30 years, our mission has been to facilitate investors’ access to the global markets.\r\n\r\nThe way in which we have done this, and continue to do so, is by allocating significant capital reserves, by providing investors with adequate trading tools, and by being a broker with a strong business ethic who remains focused on fair and regulated trading practices, and of course sound corporate governance', 'We believe everyone should have the right to access and trade the financial markets in a fair, efficient, and safe manner. It is this belief that led us to the establishment of Windsor Brokers back in 1988.\r\n\r\nFor the past 30 years, our mission has been to facilitate investors’ access to the global markets.\r\n\r\nThe way in which we have done this, and continue to do so, is by allocating significant capital reserves, by providing investors with adequate trading tools, and by being a broker with a strong business ethic who remains focused on fair and regulated trading practices, and of course sound corporate governance', NULL, NULL, 'Cyprus', 0, 'https://en.windsorbrokers.com/', 'content/companies/9a36e0de-db17-41d0-817a-ff775ceaeab4.jpeg', 1, 'CySEC', '3', 'Top 100 Member', 210, '2025-08-05 07:38:55', '2025-08-12 08:34:21'),
(20, 'AUS Global', 'AUS Global', 'AUS GLOBAL offers a wide range of trading products, competitive trading costs, safe and convenient deposit and withdrawal methods, professional 7*24 hour human customer service, adhering to the concept of customer service first, providing customers with quality services and offering the best trading experience', 'AUS GLOBAL offers a wide range of trading products, competitive trading costs, safe and convenient deposit and withdrawal methods, professional 7*24 hour human customer service, adhering to the concept of customer service first, providing customers with quality services and offering the best trading experience', NULL, NULL, 'London, UK', 1, 'https://www.ausglobaluk.com/', 'content/companies/2bbc0bb2-bd78-4d4a-91dc-1f0c57490f3c.jpg', 1, 'FCA', '3.5', 'Top 100 Member', 209, '2025-08-05 07:44:18', '2025-08-12 08:34:21'),
